solution.javascript:
class Counter {
  constructor() {
    this.count = 0
  }

  increment() {
    this.count = this.count + 1
    return this.count
  }

  decrement() {
    this.count = this.count - 1
    return this.count
  }

  reset() {
    this.count = 0
    return this.count
  }
}
